select table_name, string_agg(column_name||':'||data_type, ', ' order by ordinal_position) cols from information_schema.columns where table_schema='public' and table_name in ('orders','order_items','order_lines','sales_returns','sales_return_items','leads','inventory','distributor_payments','dealer_payments','retailer_payments','partner_payments','expenses','schemes','visit_reports','products','stock_movements','purchase_orders','purchase_returns','credit_notes') group by 1 order by 1;
